// THE POSITION — what is actually held and actually owed, as of a date coverage really reaches.
//
// This is the first capability that takes a `ReconciledLedger`, and taking one is the point: a
// position computed from an unchecked transaction list is a confident number built on a list that
// might be missing a month. The compiler is what stops that here.
//
// THE SIGN CONTRACT IS THE WHOLE MODULE. A chequing statement printing "1,200.00" means you HAVE
// $1,200. A card statement printing "2,431.07" means you OWE $2,431.07. Adding the two printed
// numbers gives $3,631.07, which is not a quantity that exists — the truth is −$1,231.07. So every
// balance here is SIGNED by what it contributes to net worth, and `fromStatementBalance` is the one
// named place a printed figure is converted. Nothing in this module guesses which convention a
// number arrived in.
//
// The proof that the contract holds is that a payment from chequing to a card MOVES NOTHING: −$300
// on one account and +$300 on the other, net worth unchanged. It is the same money in a different
// place, and a model that reports otherwise is wrong in a way that feels like progress.
import { type Money, money, sum, scale, negate } from "@/features/finance/lib/money";
import type { Txn } from "@/features/finance/lib/txn";
import { type ReconciledLedger, covered, provenance } from "@/features/finance/lib/reconcile";

export type AccountKind = "checking" | "savings" | "credit" | "loan" | "investment";

/** The kinds where a positive printed balance means money you OWE. */
const DEBT_KINDS: ReadonlySet<AccountKind> = new Set<AccountKind>(["credit", "loan"]);

/** The kinds you can actually pay a bill out of this week. An investment is not liquidity. */
const LIQUID_KINDS: ReadonlySet<AccountKind> = new Set<AccountKind>(["checking", "savings"]);

export const isDebtKind = (k: AccountKind): boolean => DEBT_KINDS.has(k);

/** What kind of thing an account is. Static facts, not derived from transactions. */
export interface AccountDeclaration {
  readonly account: string;
  readonly institution: string;
  readonly kind: AccountKind;
  readonly currency: string;
  /** Positive minor units. ABSENT means unknown — never zero, which would read as "no credit". */
  readonly creditLimit?: number;
  /** Annual rate as a fraction: 0.2499 for 24.99%. Absent means unknown. */
  readonly apr?: number;
  /** Positive minor units the institution will accept this cycle. */
  readonly minimumPayment?: number;
}

export interface AccountBalance {
  readonly account: string;
  /** `YYYY-MM-DD` the balance was true on. */
  readonly asOf: string;
  /** SIGNED by contribution to net worth — a card you owe $2,431.07 on is −243107. Build it with
   *  `fromStatementBalance` rather than by hand. */
  readonly balance: Money;
}

/**
 * Convert the number a statement PRINTS into the signed convention.
 *
 * A debt statement prints what you owe as a positive number, because from the institution's side it
 * is an asset. Net worth needs the other side of that. A card in credit (you overpaid) prints a
 * negative and comes back positive, which is also right — negation is the whole rule, and it holds
 * in both directions rather than being a special case for the common one.
 */
export const fromStatementBalance = (kind: AccountKind, printed: Money): Money =>
  isDebtKind(kind) ? negate(printed) : printed;

export interface AccountPosition {
  readonly account: string;
  readonly institution: string;
  readonly kind: AccountKind;
  /** Signed, rolled forward from the stated balance to `asOf`. */
  readonly balance: Money;
  readonly asOf: string;
  /** How many transactions were applied on top of the stated balance to get here. */
  readonly rolledForward: number;
  readonly isDebt: boolean;
  /** POSITIVE amount owed. Present only when the account is actually in debt. */
  readonly owed?: Money;
  readonly creditLimit?: Money;
  readonly available?: Money;
  /** 0-1. UNDEFINED when the limit is unknown — 0 would read as "nothing used", which is the
   *  opposite of not knowing. */
  readonly utilisation?: number;
  readonly apr?: number;
  /** What this debt costs per day at its APR. The number that makes a balance feel like a bill. */
  readonly dailyInterest?: Money;
  readonly minimumPayment?: Money;
}

export interface Position {
  /** The date this is true as of — the ledger's coverage, never later. */
  readonly asOf: string;
  readonly currency: string;
  readonly accounts: readonly AccountPosition[];
  /** Assets minus debts. The one number, and it is signed. */
  readonly netWorth: Money;
  /** What could pay a bill this week — chequing and savings only. */
  readonly liquid: Money;
  /** POSITIVE total owed across every debt. */
  readonly totalDebt: Money;
  /** What the debt costs per day, together. */
  readonly dailyInterest: Money;
  /** The minimums that keep every account current. */
  readonly minimumsDue: Money;
  /** Balance-weighted APR across debts whose rate is known. Undefined when none is. */
  readonly weightedApr?: number;
  /** False when anything below is standing on something unchecked or unknown. */
  readonly complete: boolean;
  readonly problems: readonly string[];
  readonly provenance: string;
}

const round = (n: number): number => Math.round(n);

export function position(
  ledger: ReconciledLedger,
  declarations: readonly AccountDeclaration[],
  balances: readonly AccountBalance[],
  currency: string,
): Position {
  const problems: string[] = [];
  const byAccount = new Map(declarations.map((d) => [d.account, d]));
  const balanceOf = new Map(balances.map((b) => [b.account, b]));
  const rows = covered(ledger);

  // AN UNDECLARED ACCOUNT IS NOT A ROUNDING ERROR. Without its kind there is no way to know whether
  // its transactions are money you have or money you owe, and folding it in either way invents a
  // sign. It is named and left out, and the position says it is incomplete because of it.
  for (const account of new Set(rows.map((t) => t.account))) {
    if (!byAccount.has(account)) {
      problems.push(
        `'${account}' has transactions but no declaration — nothing here can tell whether that is money you have or money you owe, so it is left out entirely`,
      );
    }
  }

  const out: AccountPosition[] = [];
  for (const d of declarations) {
    if (d.currency !== currency) {
      problems.push(
        `'${d.account}' is in ${d.currency}, not ${currency} — it is excluded rather than converted, because a rate is a decision and a net worth across currencies is not one number`,
      );
      continue;
    }
    const stated = balanceOf.get(d.account);
    if (!stated) {
      problems.push(`'${d.account}' is declared but has no balance — its transactions cannot say what it holds, only how it moved`);
      continue;
    }
    if (stated.asOf > ledger.through) {
      problems.push(
        `'${d.account}' has a balance dated ${stated.asOf}, past the ${ledger.through} the ledger actually covers — the transactions between them are not here to check it`,
      );
    }

    // ONLY WHAT CAME AFTER. A transaction dated on or before the stated balance is already inside
    // that balance; applying it again double-counts, and the error is invisible because the result
    // is still a plausible number.
    const after = rows.filter((t: Txn) => t.account === d.account && t.date > stated.asOf);
    const movement = sum(after.map((t) => t.amount), currency);
    const balance = money(stated.balance.minor + movement.minor, currency);

    const isDebt = isDebtKind(d.kind);
    const owedMinor = balance.minor < 0 ? -balance.minor : 0;
    const owed = owedMinor > 0 ? money(owedMinor, currency) : undefined;

    const creditLimit = d.creditLimit !== undefined ? money(d.creditLimit, currency) : undefined;
    if (d.kind === "credit" && creditLimit === undefined) {
      problems.push(`'${d.account}' is a credit line with no limit — its utilisation is UNKNOWN, which is not the same as 0%`);
    }
    if (isDebt && owed && d.apr === undefined) {
      problems.push(`'${d.account}' owes ${owedMinor} minor units at an unknown APR — the daily interest and weighted APR below both understate what this costs`);
    }

    out.push({
      account: d.account,
      institution: d.institution,
      kind: d.kind,
      balance,
      asOf: ledger.through,
      rolledForward: after.length,
      isDebt,
      ...(owed ? { owed } : {}),
      ...(creditLimit ? { creditLimit } : {}),
      ...(creditLimit ? { available: money(creditLimit.minor - owedMinor, currency) } : {}),
      ...(creditLimit && creditLimit.minor > 0 ? { utilisation: Math.round((owedMinor / creditLimit.minor) * 1000) / 1000 } : {}),
      ...(d.apr !== undefined ? { apr: d.apr } : {}),
      ...(d.apr !== undefined && owed ? { dailyInterest: scale(owed, d.apr / 365) } : {}),
      ...(d.minimumPayment !== undefined && owed ? { minimumPayment: money(d.minimumPayment, currency) } : {}),
    });
  }

  const netWorth = sum(out.map((a) => a.balance), currency);
  const liquid = sum(out.filter((a) => LIQUID_KINDS.has(a.kind)).map((a) => a.balance), currency);
  const debts = out.filter((a) => a.owed);
  const totalDebtMinor = debts.reduce((n, a) => n + a.owed!.minor, 0);

  const rated = debts.filter((a) => a.apr !== undefined);
  const ratedTotal = rated.reduce((n, a) => n + a.owed!.minor, 0);

  if (ledger.unverified) {
    problems.push(`the ledger under this was NOT reconciled: ${ledger.caveat}`);
  }

  return {
    asOf: ledger.through,
    currency,
    accounts: out,
    netWorth,
    liquid,
    totalDebt: money(totalDebtMinor, currency),
    dailyInterest: sum(debts.map((a) => a.dailyInterest ?? money(0, currency)), currency),
    minimumsDue: sum(debts.map((a) => a.minimumPayment ?? money(0, currency)), currency),
    ...(ratedTotal > 0
      ? { weightedApr: Math.round((rated.reduce((n, a) => n + a.owed!.minor * a.apr!, 0) / ratedTotal) * 10000) / 10000 }
      : {}),
    complete: problems.length === 0,
    problems,
    provenance: `${provenance(ledger)} · position as of ${ledger.through}`,
  };
}

/** What a whole year of carrying today's debt costs, if nothing is paid down. Often the number that
 *  changes somebody's mind, so it is given rather than left as an exercise. */
export const annualInterestCost = (p: Position): Money => scale(p.dailyInterest, 365);

/** Utilisation across every credit line together — the figure a score actually reads. */
export function overallUtilisation(p: Position): number | undefined {
  const lines = p.accounts.filter((a) => a.kind === "credit" && a.creditLimit);
  const limit = lines.reduce((n, a) => n + a.creditLimit!.minor, 0);
  if (limit <= 0) return undefined;
  return Math.round((lines.reduce((n, a) => n + (a.owed?.minor ?? 0), 0) / limit) * 1000) / 1000;
}

/** Debts worst-rate first — the order avalanche pays them in, and the order to read them in. */
export const byCost = (p: Position): readonly AccountPosition[] =>
  p.accounts.filter((a) => a.owed).sort((a, b) => (b.apr ?? -1) - (a.apr ?? -1));

