import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import type { Txn } from "@/features/finance/lib/txn";
import { type StatementPeriod, reconcile, unverifiedLedger } from "@/features/finance/lib/reconcile";
import {
  type AccountBalance,
  type AccountDeclaration,
  annualInterestCost,
  byCost,
  fromStatementBalance,
  isDebtKind,
  overallUtilisation,
  position,
} from "@/features/finance/lib/position";

// SYNTHETIC FIXTURES ONLY. No real statement, balance or account number belongs in this repo.
const usd = (major: number): Money => fromMajor(major, "USD");
const tx = (date: string, description: string, major: number, account: string): Txn => ({
  date,
  description,
  amount: usd(major),
  account,
});

const CHECKING: AccountDeclaration = {
  account: "checking",
  institution: "Example Bank",
  kind: "checking",
  currency: "USD",
};
const CARD: AccountDeclaration = {
  account: "card",
  institution: "Example Card Co",
  kind: "credit",
  currency: "USD",
  creditLimit: usd(5000).minor,
  apr: 0.2499,
  minimumPayment: usd(75).minor,
};

const bal = (account: string, major: number, asOf = "2026-06-01"): AccountBalance => ({
  account,
  asOf,
  balance: usd(major),
});

/** A ledger with no reconcile behind it — enough to exercise the mechanics of `position` without
 *  re-testing reconcile. Every position built on one is deliberately `complete: false`. */
const ledger = (txns: Txn[], through = "2026-06-30") =>
  unverifiedLedger(txns, through, "synthetic fixture");

/** A genuinely RECONCILED ledger, so the clean-run case is not asserted against a fixture that
 *  could never be clean. Throws rather than silently handing back undefined. */
function tight(txns: Txn[], periods: StatementPeriod[]) {
  const r = reconcile(txns, periods);
  if (!r.ledger) throw new Error(`fixture does not reconcile: ${JSON.stringify(r.problems)}`);
  return r.ledger;
}

describe("fromStatementBalance — the one place a printed figure is converted", () => {
  it("negates what a debt statement prints, because that is what you OWE", () => {
    expect(fromStatementBalance("credit", usd(2431.07)).minor).toBe(usd(-2431.07).minor);
    expect(fromStatementBalance("loan", usd(18000)).minor).toBe(usd(-18000).minor);
  });

  it("leaves an asset alone", () => {
    expect(fromStatementBalance("checking", usd(1200)).minor).toBe(usd(1200).minor);
    expect(fromStatementBalance("savings", usd(400)).minor).toBe(usd(400).minor);
  });

  it("holds in BOTH directions — an overpaid card prints a negative and is money you have", () => {
    expect(fromStatementBalance("credit", usd(-50)).minor).toBe(usd(50).minor);
  });

  it("knows which kinds are debts", () => {
    expect(isDebtKind("credit")).toBe(true);
    expect(isDebtKind("loan")).toBe(true);
    expect(isDebtKind("checking")).toBe(false);
    expect(isDebtKind("investment")).toBe(false);
  });
});

describe("position — the sign contract", () => {
  it("does NOT add a printed card balance to a chequing balance", () => {
    // $1,200 held and $2,431.07 owed is −$1,231.07, not $3,631.07. Adding the two printed numbers is
    // the single most consequential mistake this module can make.
    const p = position(
      ledger([]),
      [CHECKING, CARD],
      [bal("checking", 1200), { account: "card", asOf: "2026-06-01", balance: fromStatementBalance("credit", usd(2431.07)) }],
      "USD",
    );
    expect(p.netWorth.minor).toBe(usd(-1231.07).minor);
    expect(p.totalDebt.minor).toBe(usd(2431.07).minor);
    expect(p.liquid.minor).toBe(usd(1200).minor);
  });

  it("a payment from chequing to a card MOVES NOTHING", () => {
    // The proof the contract holds end to end: the same $300 leaves one account and arrives at the
    // other, so net worth is identical before and after. A model that reports an improvement here is
    // wrong in a way that feels like progress.
    const before = position(
      ledger([]),
      [CHECKING, CARD],
      [bal("checking", 1200), bal("card", -2000)],
      "USD",
    );
    const after = position(
      ledger([tx("2026-06-10", "PAYMENT TO CARD", -300, "checking"), tx("2026-06-10", "PAYMENT RECEIVED", 300, "card")]),
      [CHECKING, CARD],
      [bal("checking", 1200), bal("card", -2000)],
      "USD",
    );
    expect(after.netWorth.minor).toBe(before.netWorth.minor);
    // But it is not a no-op: liquidity fell and the debt shrank.
    expect(after.liquid.minor).toBe(usd(900).minor);
    expect(after.totalDebt.minor).toBe(usd(1700).minor);
  });

  it("an investment is not liquidity", () => {
    const p = position(
      ledger([]),
      [CHECKING, { account: "broker", institution: "Example Broker", kind: "investment", currency: "USD" }],
      [bal("checking", 1200), bal("broker", 40000)],
      "USD",
    );
    expect(p.netWorth.minor).toBe(usd(41200).minor);
    expect(p.liquid.minor).toBe(usd(1200).minor);
  });
});

describe("position — rolling a balance forward", () => {
  it("applies only what came AFTER the stated balance", () => {
    // A transaction dated on or before the stated balance is already inside it. Applying it again
    // double-counts, and the result is still a plausible number, which is why it needs a test.
    const p = position(
      ledger([
        tx("2026-05-20", "BEFORE THE BALANCE", -100, "checking"),
        tx("2026-06-01", "ON THE BALANCE DATE", -50, "checking"),
        tx("2026-06-10", "AFTER", -25, "checking"),
      ]),
      [CHECKING],
      [bal("checking", 1200, "2026-06-01")],
      "USD",
    );
    expect(p.accounts[0].rolledForward).toBe(1);
    expect(p.accounts[0].balance.minor).toBe(usd(1175).minor);
  });

  it("stops at the ledger's coverage, never later", () => {
    const p = position(
      ledger([tx("2026-06-10", "COVERED", -25, "checking"), tx("2026-07-10", "BEYOND COVERAGE", -900, "checking")], "2026-06-30"),
      [CHECKING],
      [bal("checking", 1200)],
      "USD",
    );
    expect(p.asOf).toBe("2026-06-30");
    expect(p.accounts[0].rolledForward).toBe(1);
    expect(p.accounts[0].balance.minor).toBe(usd(1175).minor);
  });

  it("says so when a balance is dated past what the ledger covers", () => {
    const p = position(ledger([], "2026-06-30"), [CHECKING], [bal("checking", 1200, "2026-07-15")], "USD");
    expect(p.complete).toBe(false);
    expect(p.problems.join(" ")).toContain("past the 2026-06-30");
  });
});

describe("position — what is unknown is not zero", () => {
  it("leaves utilisation UNDEFINED for a credit line with no limit", () => {
    const noLimit: AccountDeclaration = { ...CARD, creditLimit: undefined };
    const p = position(ledger([]), [noLimit], [bal("card", -2000)], "USD");
    // 0% utilised is an excellent score. Not knowing is not an excellent score.
    expect(p.accounts[0].utilisation).toBeUndefined();
    expect(p.accounts[0].available).toBeUndefined();
    expect(p.problems.join(" ")).toContain("UNKNOWN");
    expect(p.complete).toBe(false);
  });

  it("names a debt with no APR, because every interest figure then understates", () => {
    const noApr: AccountDeclaration = { ...CARD, apr: undefined };
    const p = position(ledger([]), [noApr], [bal("card", -2000)], "USD");
    expect(p.accounts[0].dailyInterest).toBeUndefined();
    expect(p.weightedApr).toBeUndefined();
    expect(p.problems.join(" ")).toContain("understate");
  });

  it("refuses to guess the sign of an account it was never told about", () => {
    const p = position(ledger([tx("2026-06-10", "MYSTERY", -300, "unknown-account")]), [CHECKING], [bal("checking", 1200)], "USD");
    expect(p.complete).toBe(false);
    expect(p.problems.join(" ")).toContain("'unknown-account'");
    // Left out entirely rather than folded in with an invented sign.
    expect(p.netWorth.minor).toBe(usd(1200).minor);
  });

  it("excludes another currency rather than converting it", () => {
    const eur: AccountDeclaration = { account: "eu", institution: "Example EU", kind: "checking", currency: "EUR" };
    const p = position(ledger([]), [CHECKING, eur], [bal("checking", 1200), { account: "eu", asOf: "2026-06-01", balance: fromMajor(900, "EUR") }], "USD");
    expect(p.accounts).toHaveLength(1);
    expect(p.netWorth.minor).toBe(usd(1200).minor);
    expect(p.problems.join(" ")).toContain("not one number");
  });

  it("carries an unverified ledger's caveat forward instead of laundering it", () => {
    const p = position(unverifiedLedger([], "2026-06-30", "Chase export has no opening balance"), [CHECKING], [bal("checking", 1200)], "USD");
    expect(p.complete).toBe(false);
    expect(p.problems.join(" ")).toContain("Chase export has no opening balance");
    expect(p.provenance).toMatch(/^UNVERIFIED/);
  });
});

describe("position — what the debt costs", () => {
  const p = () =>
    position(
      ledger([]),
      [
        CHECKING,
        CARD,
        { account: "loan", institution: "Example Loan Co", kind: "loan", currency: "USD", apr: 0.0699, minimumPayment: usd(220).minor },
      ],
      [bal("checking", 1200), bal("card", -2000), bal("loan", -8000)],
      "USD",
    );

  it("prices each debt per day at its own rate", () => {
    const card = p().accounts.find((a) => a.account === "card")!;
    expect(card.dailyInterest!.minor).toBe(Math.round(usd(2000).minor * (0.2499 / 365)));
    expect(card.utilisation).toBe(0.4);
    expect(card.available!.minor).toBe(usd(3000).minor);
  });

  it("weights the APR by BALANCE, not by account count", () => {
    // Two accounts, but $8,000 at 6.99% and $2,000 at 24.99% is not a 15.99% problem. Averaging the
    // rates would say it is, and would send somebody at the wrong debt first.
    const w = p().weightedApr!;
    expect(w).toBeCloseTo((2000 * 0.2499 + 8000 * 0.0699) / 10000, 4);
    expect(w).toBeLessThan((0.2499 + 0.0699) / 2);
  });

  it("adds up the minimums that keep everything current", () => {
    expect(p().minimumsDue.minor).toBe(usd(295).minor);
  });

  it("says what a year of carrying it costs", () => {
    expect(annualInterestCost(p()).minor).toBe(Math.round(p().dailyInterest.minor * 365));
  });

  it("orders debts worst-rate first", () => {
    expect(byCost(p()).map((a) => a.account)).toEqual(["card", "loan"]);
  });

  it("reports utilisation across every credit line together", () => {
    expect(overallUtilisation(p())).toBe(0.4);
    expect(overallUtilisation(position(ledger([]), [CHECKING], [bal("checking", 1200)], "USD"))).toBeUndefined();
  });

  it("charges no interest on a debt that is paid off", () => {
    const clear = position(ledger([]), [CARD], [bal("card", 0)], "USD");
    expect(clear.totalDebt.minor).toBe(0);
    expect(clear.dailyInterest.minor).toBe(0);
    expect(clear.accounts[0].owed).toBeUndefined();
    expect(clear.accounts[0].utilisation).toBe(0);
    // And a minimum payment is not due on a cleared card.
    expect(clear.minimumsDue.minor).toBe(0);
  });
});

describe("position — a clean run says so", () => {
  const june = (account: string, signed: Money): StatementPeriod => ({
    account,
    from: "2026-06-01",
    to: "2026-06-30",
    opening: signed,
    closing: signed,
  });

  it("is complete when nothing is unknown, unchecked or undeclared", () => {
    const l = tight([], [june("checking", usd(1200)), june("card", fromStatementBalance("credit", usd(2000)))]);
    const p = position(l, [CHECKING, CARD], [bal("checking", 1200, "2026-06-30"), bal("card", -2000, "2026-06-30")], "USD");
    expect(p.problems).toEqual([]);
    expect(p.complete).toBe(true);
    expect(p.provenance).toMatch(/^reconciled/);
    expect(p.provenance).toContain("position as of 2026-06-30");
    expect(p.netWorth.minor).toBe(usd(-800).minor);
  });

  it("stops being complete the moment one thing is unknown", () => {
    const l = tight([], [june("checking", usd(1200)), june("card", fromStatementBalance("credit", usd(2000)))]);
    const p = position(l, [CHECKING, { ...CARD, apr: undefined }], [bal("checking", 1200, "2026-06-30"), bal("card", -2000, "2026-06-30")], "USD");
    expect(p.complete).toBe(false);
  });
});
